/* ---------- вотчдог фермы номеров Simbye (health сессии + застрявшие OTP + истечение) ----------
 * Отдельный медленный цикл (60с): обходит тенантов, гоняет simbye.tick только там, где ферма реально
 * настроена/используется. Сигналы владельцу идут через engine.sendReport (Telegram-мост). */
setInterval(() => {
  try {
    for (const tid of store.listTenants()) {
      store.runInTenant(tid, () => {
        const db = store.get();
        const f = db.settings && db.settings.simbyeFarm;
        const cfg = db.settings && db.settings.simbye;
        const has = (f && Array.isArray(f.accounts) && f.accounts.length) || (cfg && (cfg.url || cfg.token));
        if (!has && !process.env.LUMEN_SIMBYE_WORKER_URL) return; // ничего не настроено — пропускаем
        simbye.tick(db, store, { notifyOwner: (d, msg) => { try { engine.sendReport(d, msg); } catch (_) {} } })
          .catch(e => console.error('[simbye.tick]', tid, e && e.message))
          .finally(() => { try { ensureFarmChannelNumbers(db); } catch (_) {} }); // после авто-детекта номеров — линковка в WA/TG
        autopilotReconcile(db).catch(e => console.error('[simbye.autopilot]', tid, e && e.message));
      });
    }
  } catch (e) { console.error('[simbye watchdog]', e && e.message); }
}, 60000);

/* Автопилот фермы: когда номер РЕАЛЬНО подключился в WA/TG-воркере — двигаем этап,
 * закрепляем секреты (2FA/почта), применяем персону из шаблона агентства, добиваем до «активен».
 * Отвалился — сигнал. Только при template.autopilot. Живые вызовы воркеров — best-effort. */
async function autopilotReconcile(db) {
  const t = simbye.template(db);
  if (!t.autopilot) return;
  const f = simbye.farm(db);
  if (!f.accounts.length) return;
  let waLive = {}, tgLive = {};
  try { if (waWorkerReady(db)) waLive = (await waGrayApi(db, 'GET', '/sessions')).sessions || {}; } catch (_) {}
  try { if (tgWorkerReady(db)) tgLive = (await tgGrayApi(db, 'GET', '/sessions')).sessions || {}; } catch (_) {}
  const chans = [
    { ch: 'wa', live: waLive, sid: waGraySid, api: waGrayApi, profile: (p) => ({ name: p.name, about: p.bio, photoUrl: p.avatar }) },
    { ch: 'tg', live: tgLive, sid: tgGraySid, api: tgGrayApi, profile: (p) => ({ firstName: p.name, about: p.bio, photoUrl: p.avatar }) },
  ];
  let idx = 0;
  for (const acc of f.accounts) {
    for (const cfg of chans) {
      const s = cfg.live[cfg.sid(acc.phone)];
      const connected = s && s.status === 'connected';
      if (connected) {
        const need = simbye.onConnected(db, acc, cfg.ch);
        // персону применяем ТОЛЬКО у номеров, заведённых через ферму (autoManage) — чужие/готовые аккаунты не трогаем
        if (need && acc.autoManage === true) {
          const p = simbye.personaFor(db, acc, idx);
          try { await cfg.api(db, 'POST', '/sessions/' + cfg.sid(acc.phone) + '/profile', cfg.profile(p)); const c = simbye.chan(acc, cfg.ch); c.personaPending = false; c.persona = p; } catch (_) {}
        }
        simbye.maybeActivate(db, acc, cfg.ch);
      } else {
        simbye.onDisconnected(db, acc, cfg.ch);
      }
    }
    idx++;
  }
  try { store.save(); } catch (_) {}
}

/* Связать номера фермы с воркерами WA/TG: чтобы QR-подключение, прогрев и детект «активен» работали.
 * Каждый номер фермы (с телефоном) заводится в waGray.numbers и tgGray.numbers (digits-only, как в их роутах). */
function ensureFarmChannelNumbers(db) {
  const f = db.settings && db.settings.simbyeFarm;
  if (!f || !Array.isArray(f.accounts)) return;
  db.settings.waGray = db.settings.waGray || { numbers: [], warmup: { running: false, perDay: 16 } };
  db.settings.waGray.numbers = db.settings.waGray.numbers || [];
  db.settings.tgGray = db.settings.tgGray || { numbers: [] };
  db.settings.tgGray.numbers = db.settings.tgGray.numbers || [];
  const tpl = simbye.template(db);
  let changed = false;
  f.accounts.forEach((acc, i) => {
    if (!acc.phone || (acc.provision && acc.provision.state !== 'received')) return;
    const digits = String(acc.phone).replace(/[^0-9]/g, '');
    if (!digits) return;
    const label = ((acc.channels && acc.channels.wa && acc.channels.wa.persona && acc.channels.wa.persona.name)) || ('Simbye ' + (acc.country || '').toUpperCase());
    if ((tpl.targets || {}).wa !== 0 && !db.settings.waGray.numbers.some(n => n.phone === digits)) {
      db.settings.waGray.numbers.push({ phone: digits, label, roles: { send: true, call: false }, source: 'simbye', farmId: acc.id, addedAt: Date.now() }); changed = true;
    }
    if ((tpl.targets || {}).tg !== 0 && !db.settings.tgGray.numbers.some(n => n.phone === digits)) {
      const p = simbye.personaFor(db, acc, i);
      db.settings.tgGray.numbers.push({ phone: digits, label, persona: { name: p.name || '', avatar: p.avatar || '', about: p.bio || '', mode: 'qualifier', brokerId: null }, source: 'simbye', farmId: acc.id, addedAt: Date.now() }); changed = true;
    }
  });
  if (changed) { try { store.save(); } catch (_) {} }
}

/* ---------- авторизация ---------- */
const sha = (s) => crypto.createHash('sha256').update(s).digest('hex');
const DEFAULT_PASS = 'lumen2026';
/* SEC: пароли — scrypt с солью (формат s2$salt$hash). verifyPassword понимает и старый SHA256
   (legacy) для бесшовной миграции: при удачном входе legacy-хэш перезаписывается на scrypt (upgrade-on-login). */
function hashPassword(pw) { const salt = crypto.randomBytes(16).toString('hex'); return 's2$' + salt + '$' + crypto.scryptSync(String(pw), salt, 64).toString('hex'); }
function isLegacyHash(stored) { return !!stored && !String(stored).startsWith('s2$'); }
function verifyPassword(pw, stored) {
  if (!stored) return false;
  try {
    if (String(stored).startsWith('s2$')) { const [, salt, h] = String(stored).split('$'); const cand = crypto.scryptSync(String(pw), salt, 64).toString('hex'); const a = Buffer.from(h, 'hex'), b = Buffer.from(cand, 'hex'); return a.length === b.length && crypto.timingSafeEqual(a, b); }
    return sha(String(pw)) === stored; /* legacy SHA256 */
  } catch (e) { return false; }
}
/* ===== Вход/активация по КОДУ из письма (6 цифр) — безопасно =====
   Код: 6 цифр, хранится ТОЛЬКО как sha256(email|code|salt) в реестре, одноразовый, TTL 10 мин, ≤5 попыток.
   Никогда не логируем и не отдаём код клиенту (только письмом). Анти-enumeration — на уровне эндпоинта. */
function _emailCodeHash(email, code) { return crypto.createHash('sha256').update(String(email) + '|' + String(code) + '|' + (process.env.CODE_SALT || 'lumen-code-salt-v1')).digest('hex'); }
function issueEmailCode(reg, email) {
  reg.emailCodes = reg.emailCodes || {};
  const code = String(crypto.randomInt(0, 1000000)).padStart(6, '0');
  reg.emailCodes[email] = { hash: _emailCodeHash(email, code), exp: Date.now() + 10 * 60e3, tries: 0, at: Date.now() };
  store.saveRegistry();
  return code;
}
function checkEmailCode(reg, email, code) {
  reg.emailCodes = reg.emailCodes || {};
  const rec = reg.emailCodes[email];
  if (!rec) return { ok: false, error: 'Код не запрошен или уже использован' };
  if (Date.now() > rec.exp) { delete reg.emailCodes[email]; store.saveRegistry(); return { ok: false, error: 'Код истёк — запросите новый' }; }
  if ((rec.tries || 0) >= 5) { delete reg.emailCodes[email]; store.saveRegistry(); return { ok: false, error: 'Слишком много попыток — запросите новый код' }; }
  rec.tries = (rec.tries || 0) + 1; store.saveRegistry();
  const want = Buffer.from(rec.hash), got = Buffer.from(_emailCodeHash(email, String(code || '').trim()));
  const ok = want.length === got.length && crypto.timingSafeEqual(want, got);
  if (!ok) return { ok: false, error: 'Неверный код' };
  delete reg.emailCodes[email]; store.saveRegistry();   /* одноразовый */
  return { ok: true };
}
/* найти аккаунт по e-mail: владелец (byEmail) или брокер (скан тенантов). Возвращает {tid, role, brokerId} | null */
function resolveEmailAccount(reg, email) {
  const otid = reg.byEmail[email];
  if (otid && store.listTenants().includes(otid)) return { tid: otid, role: 'owner', brokerId: null };
  for (const tid of store.listTenants()) {
    let hit = null;
    store.runInTenant(tid, () => { const br = (store.get().brokers || []).find(x => x.email && x.email.toLowerCase() === email && x.active !== false); if (br) hit = { tid, role: 'broker', brokerId: br.id }; });
    if (hit) return hit;
  }
  return null;
}
/* создать сессию для аккаунта (owner/broker) в тенанте + реестре; вернуть sid */
function mkTenantSession(reg, acct, req) {
  const sid = crypto.randomBytes(16).toString('hex');
  store.runInTenant(acct.tid, () => {
    const tdb = store.get();
    tdb.settings.auth = tdb.settings.auth || {}; tdb.settings.auth.sessions = tdb.settings.auth.sessions || {};
    tdb.settings.auth.sessions[sid] = { at: Date.now(), role: acct.role, brokerId: acct.brokerId || undefined, ip: clientIp(req), ua: req.headers['user-agent'] || '', lastSeen: Date.now() };
    const keys = Object.keys(tdb.settings.auth.sessions); if (keys.length > 20) delete tdb.settings.auth.sessions[keys[0]];
    store.saveNow();
  });
  reg.sessions[sid] = { tid: acct.tid, at: Date.now() }; store.saveRegistry();
  return sid;
}
/* SaaS: тарифные планы (лимиты работают без Stripe; оплата подключится позже) */
const PLANS = {
  trial: { name: 'Триал', maxBrokers: 3, maxLeads: 300, maxNumbers: 1, price: 0 },
  starter: { name: 'Starter', maxBrokers: 5, maxLeads: 2000, maxNumbers: 3, price: 49 },
  pro: { name: 'Pro', maxBrokers: 25, maxLeads: 50000, maxNumbers: 15, price: 149 },
};
function planOf(tid) { try { const t = store.getRegistry().tenants[tid]; return PLANS[(t && t.plan) || 'trial'] || PLANS.trial; } catch (e) { return PLANS.trial; } }
/* ЛИМИТЫ по РЕАЛЬНОМУ тарифу биллинга (broker/agency/network — как на сайте), а не по legacy-реестру (trial/starter/pro).
   Пробел, который ловил клиент: оплатил «Агентство» → billing.plan='agency', status='active', но реестр остался 'trial'
   → фичи (WA-номера по QR и пр.) блокировались. Теперь гейты читают активную подписку напрямую. */
const PLAN_LIMITS = {
  trial:   { name: 'Триал',     maxBrokers: 3,   maxLeads: 300,        maxNumbers: 1 },
  broker:  { name: 'Брокер',    maxBrokers: 1,   maxLeads: 400,        maxNumbers: 3 },
  agency:  { name: 'Агентство', maxBrokers: 200, maxLeads: 1000000000, maxNumbers: 15 },
  network: { name: 'Сеть',      maxBrokers: 1e9, maxLeads: 1e9,        maxNumbers: 100 },
};
/* эффективный тариф тенанта: активная подписка биллинга — источник правды; иначе триал. db — из store.get() в обработчике. */
function effectivePlan(db) {
  try {
    const b = db && db.settings && db.settings.billing;
    if (b && b.status === 'active' && b.plan && PLAN_LIMITS[b.plan]) {
      const lim = PLAN_LIMITS[b.plan];
      const seats = +b.seats || 0;
      return seats ? Object.assign({}, lim, { maxBrokers: Math.max(lim.maxBrokers, seats) }) : lim;
    }
  } catch (_) { }
  return PLAN_LIMITS.trial;
}

