/* blocks подборки: из сохранённых или синтез из legacy custom */
function collBlocks(c) {
  if (Array.isArray(c.blocks) && c.blocks.length) return c.blocks;
  const cust = c.custom || {};
  const hid = cust.hidden || [];
  let ids = (c.propertyIds || []).slice();
  if (cust.order && cust.order.length) ids = cust.order.filter((x) => ids.includes(x)).concat(ids.filter((x) => !cust.order.includes(x)));
  const b = [];
  b.push({ id: 'b_cover', t: 'cover', v: 'blue', data: {} });
  b.push({ id: 'b_hello', t: 'hello', v: 'std', hidden: hid.includes('hello'), data: {} });
  b.push({ id: 'b_sep', t: 'sep', v: 'blue', hidden: hid.includes('sep'), data: {} });
  /* чередуем варианты карточек объектов — соседние проекты выглядят по-разному (не «всё full») */
  const projVars = ['full', 'gallery', 'full', 'compact'];
  ids.forEach((pid, i) => {
    const ov = (cust.props || {})[pid] || {};
    b.push({ id: 'b_p_' + pid, t: 'proj', v: (ov.v || projVars[i % projVars.length]), data: { pid, hookTitle: ov.hookTitle || '', blurb: ov.blurb || '', whyRent: ov.whyRent || null } });
  });
  b.push({ id: 'b_cta', t: 'cta', v: 'blue', hidden: hid.includes('cta'), data: {} });
  b.push({ id: 'b_why', t: 'why', v: 'std', hidden: hid.includes('why'), data: {} });
  b.push({ id: 'b_final', t: 'final', v: 'blue', hidden: hid.includes('final'), data: {} });
  return b;
}

/* санитайз blocks при сохранении из редактора */
function sanitizeBlocks(raw) {
  if (!Array.isArray(raw)) return null;
  const okUrl = (s) => /^(assets\/|\/assets\/|https?:\/\/)/.test(s);
  const str = (s, n) => String(s == null ? '' : s).slice(0, n);
  const out = [];
  for (const b of raw.slice(0, 60)) {
    if (!b || !PB_TYPES[b.t]) continue;
    const meta = PB_TYPES[b.t];
    const nb = {
      id: /^[\w-]{1,40}$/.test(String(b.id)) ? String(b.id) : 'b_' + crypto.randomBytes(4).toString('hex'),
      t: b.t,
      v: meta.variants.includes(b.v) ? b.v : meta.variants[0],
      hidden: !!b.hidden,
      data: {},
    };
    const d = b.data || {};
    const put = (k, n) => { if (d[k] != null && String(d[k]).trim() !== '') nb.data[k] = str(d[k], n); };
    const putImg = (k) => { const v2 = str(d[k], 500).trim(); if (v2 && okUrl(v2)) nb.data[k] = v2; };
    const putList = (k, map) => { if (Array.isArray(d[k])) nb.data[k] = d[k].slice(0, 20).map(map).filter(Boolean); };
    put('title', 300); put('sub', 500); put('body', 4000); put('caption', 400);
    put('heading', 300); put('text', 2000); put('author', 120); put('role', 200);
    put('intro', 2000); put('badge', 120); put('btn', 80); put('freeNote', 400);
    put('hookTitle', 200); put('blurb', 800); put('officeText', 800);
    put('lede', 200); put('aboutHeading', 200); put('recTitle', 200); put('brandName', 120); put('note', 400);
    putImg('img'); putImg('photo');
    /* ручной ресайз/фокус картинок конструктора: высота и точка фокуса фона */
    const num = (k, lo, hi) => { if (d[k] != null && d[k] !== '') { const n = Math.max(lo, Math.min(hi, Math.round(+d[k]))); if (!isNaN(n)) nb.data[k] = n; } };
    num('imgH', 80, 1400); num('imgFx', 0, 100); num('imgFy', 0, 100);
    if (b.t === 'video') { const v2 = str(d.url, 500).trim(); if (v2 && /^(assets\/|\/assets\/|https?:\/\/)/.test(v2)) nb.data.url = v2; }
    if (b.t === 'proj') { nb.data.pid = str(d.pid, 30); putList('imgs', (x) => { const s2 = str(x, 500).trim(); return s2 && okUrl(s2) ? s2 : null; }); putList('whyRent', (x) => str(x, 300).trim() || null); }
    if (b.t === 'gallery') putList('imgs', (x) => { const s2 = str(x, 500).trim(); return s2 && okUrl(s2) ? s2 : null; });
    if (b.t === 'stats') putList('items', (x) => x && (x.k || x.v) ? { k: str(x.k, 120), v: str(x.v, 60) } : null);
    if (b.t === 'faq') putList('items', (x) => x && (x.q || x.a) ? { q: str(x.q, 300), a: str(x.a, 1000) } : null);
    if (b.t === 'steps' || b.t === 'benefits') putList('items', (x) => x && (x.title || x.text) ? { icon: str(x.icon, 20), title: str(x.title, 200), text: str(x.text, 600) } : null);
    if (b.t === 'compare') { put('headA', 120); put('headB', 120); putList('items', (x) => x && (x.k || x.a || x.b) ? { k: str(x.k, 160), a: str(x.a, 200), b: str(x.b, 200) } : null); }
    if (b.t === 'timeline') putList('items', (x) => x && (x.when || x.title) ? { when: str(x.when, 80), title: str(x.title, 200), text: str(x.text, 500) } : null);
    if (b.t === 'pricecards') putList('items', (x) => x && (x.name || x.price) ? { name: str(x.name, 120), price: str(x.price, 80), text: str(x.text, 600) } : null);
    if (b.t === 'team') putList('items', (x) => x && (x.name || x.role) ? { name: str(x.name, 120), role: str(x.role, 200) } : null);
    if (b.t === 'amenities') putList('items', (x) => x && (x.icon || x.label) ? { icon: str(x.icon, 20), label: str(x.label, 120) } : null);
    if (b.t === 'guarantee') putList('items', (x) => x && (x.icon || x.title || x.text) ? { icon: str(x.icon, 20), title: str(x.title, 200), text: str(x.text, 600) } : null);
    if (b.t === 'hero') { put('heading', 200); put('sub', 400); }
    if (b.t === 'bignum') { put('v', 60); put('k', 300); }
    if (b.t === 'hello' || b.t === 'why' || b.t === 'checklist') putList('bullets', (x) => str(x, 400).trim() || null);
    if (b.t === 'cta') { const h = str(d.href, 500).trim(); if (h && /^(https?:\/\/|mailto:|tel:)/.test(h)) nb.data.href = h; }
    out.push(nb);
  }
  return out.length ? out : null;
}


/* mime → расширение файла (для сохранения входящих медиа WhatsApp) */
function mimeToExt(mime) {
  const m = String(mime || '').split(';')[0].trim().toLowerCase();
  const MAP = {
    'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif',
    'video/mp4': 'mp4', 'video/3gpp': '3gp', 'video/quicktime': 'mov', 'video/webm': 'webm',
    'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'aac', 'audio/amr': 'amr', 'audio/wav': 'wav',
    'application/pdf': 'pdf', 'application/zip': 'zip', 'text/plain': 'txt', 'text/csv': 'csv',
    'application/msword': 'doc', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
    'application/vnd.ms-excel': 'xls', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  };
  if (MAP[m]) return MAP[m];
  const sub = m.split('/')[1];
  return sub ? sub.replace(/[^a-z0-9]/g, '').slice(0, 5) : '';
}

/* SEC: простой in-memory лимитер (single-instance launchd) — окно скольжения по ключу */
const _rlMap = new Map();
function rateHit(key, max, windowMs) {
  const now = Date.now(); const e = _rlMap.get(key);
  if (!e || now - e.t > windowMs) { _rlMap.set(key, { t: now, n: 1 }); return true; }
  if (e.n >= max) return false; e.n++; return true;
}

/* SEC: безопасный путь к ассету — резолвим и проверяем, что он ВНУТРИ PUBLIC/assets (защита от ../ traversal) */
function assetPathSafe(webPath) {
  const rel = String(webPath || '').replace(/^\/+/, '');
  const abs = path.resolve(PUBLIC, rel);
  const base = path.resolve(PUBLIC, 'assets');
  return (abs === base || abs.startsWith(base + path.sep)) ? abs : null;
}

/* --- запись звонка → скачать → Whisper → транскрипт в карточку лида (общая для всех провайдеров) --- */
function ingestCallRecording(db, lead, recUrl, label, durSec, authHeader) {
  (async () => {
    try {
      const r2 = await fetch(recUrl, authHeader ? { headers: { Authorization: authHeader } } : undefined);
      if (!r2.ok) throw new Error('запись недоступна: ' + r2.status);
      const buf = Buffer.from(await r2.arrayBuffer());
      if (buf.length > 24e6) throw new Error('запись больше 24МБ');
      const extM = String(recUrl).split('?')[0].match(/\.(flac|m4a|mp3|mp4|mpeg|mpga|oga|ogg|wav|webm)$/i);
      const ext = extM ? extM[1].toLowerCase() : 'mp3';
      /* 1) сохраняем ПРОИГРЫВАЕМУЮ запись в карточку (голосовой) — раньше сохранялся только текст */
      let audioUrl = null; try { const saved = tgbridge.saveMedia(buf, ext); audioUrl = saved && saved.url; } catch (e) {}
      /* 2) транскрипт (Whisper, авто-детект языка) */
      const text = String(await llm.transcribe(buf, 'call.' + ext) || '').trim();
      lead.transcripts = lead.transcripts || [];
      lead.transcripts.push({ id: store.nextId('tr'), at: Date.now(), label: (label || 'Звонок') + (durSec ? ' · ' + durSec + 'с' : ''), text: text.slice(0, 20000), audio: audioUrl || null });
      if (audioUrl) { lead.voiceNotes = lead.voiceNotes || []; lead.voiceNotes.unshift({ id: crypto.randomBytes(4).toString('hex'), url: audioUrl, dur: durSec || 0, transcript: text.slice(0, 4000), who: label || 'Звонок', at: Date.now() }); }
      ai.pushEvent(db, { type: 'call', leadId: lead.id, text: `Звонок записан и расшифрован (${text.length} симв.)` });
      store.save();
      /* 3) АВТО-АНАЛИЗ: ИИ-сводка сразу по свежему транскрипту (раньше приходилось жать вручную) */
      if (text && llm.available()) { try { const sum = await llm.summarize(db, lead); if (sum) { lead.summary = sum; lead.summaryAt = Date.now(); ai.pushEvent(db, { type: 'call', leadId: lead.id, text: 'ИИ обновил сводку по лиду после звонка' }); store.save(); } } catch (e) { console.error('[call-summary]', e.message); } }
      /* 4) ПОСТ-ЗВОНКОВАЯ РАЗВИЛКА: транскрипт + психо-паттерны → готовое первое касание в WhatsApp
         (дозвон = есть транскрипт). Кладём ЧЕРНОВИК в lead.postCall — брокер отправит его серым способом
         со своего прогретого номера (кнопка в карточке), а не автослёт. Недозвон (нет записи) сюда не
         попадает — там работает обычная текстовая цепочка касаний движка. */
      if (text && text.length > 40 && llm.available()) {
        try {
          const pc = await llm.composePostCall(db, lead, db.settings.agency.name);
          if (pc && pc.message) {
            lead.postCall = { message: pc.message, approach: pc.approach, sendSelection: !!pc.sendSelection, reason: pc.reason, at: Date.now(), sent: false };
            const apRu = { selection: 'подборка сразу', warmup: 'мягкий прогрев', connect: 'закрепиться в мессенджере' }[pc.approach] || pc.approach;
            ai.pushEvent(db, { type: 'call', leadId: lead.id, text: `ИИ подготовил касание после звонка (${apRu}) — проверьте и отправьте` });
            store.save();
          }
        } catch (e) { console.error('[post-call]', e.message); }
      }
    } catch (e) { console.error('[call-ingest]', e.message); }
  })();
}

/* --- Telnyx Call Control: click-to-call (звонок брокеру → соединение с клиентом → запись) --- */
/* ключ Telnyx: сперва из настроек тенанта, иначе платформенный из env TELNYX_API_KEY (Railway).
   Так один аккаунт-менеджер обслуживает всех + позже — провижн Managed Accounts тем же ключом. */
/* платформенный Telnyx-ключ (SaaS): все агентства покупают через ОДИН наш аккаунт, провайдер скрыт.
   Приоритет: env → платформенный реестр → ключ тенанта (легаси). */
function platformTelnyxKey() { try { const r = store.getRegistry(); return (r.platformTelnyx && r.platformTelnyx.key) || ''; } catch (_) { return ''; } }
function telnyxKey(t) { return process.env.TELNYX_API_KEY || platformTelnyxKey() || (t && t.key) || ''; }
const TELNYX_MARKUP = 2;   /* наценка платформы $/номер в мес (показываем клиенту цену УЖЕ с наценкой; себестоимость скрыта) */
async function telnyxApi(db, method, pathx, body) {
  const t = db.settings.telephony || {};
  const r = await fetch('https://api.telnyx.com/v2' + pathx, { method, headers: { Authorization: 'Bearer ' + telnyxKey(t), 'Content-Type': 'application/json' }, body: body ? JSON.stringify(body) : undefined });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error('telnyx ' + r.status + ': ' + ((j.errors && j.errors[0] && j.errors[0].detail) || 'ошибка'));
  return j;
}
function telnyxWebhook(db) { const base = process.env.PUBLIC_BASE_URL || tunnelUrl() || global.LUMEN_BASE || ''; return (base && !/localhost|127\.0\.0\.1/.test(base)) ? base.replace(/\/$/, '') + '/hooks/telnyx?key=' + encodeURIComponent(db.settings.hooks.secret) : undefined; }
/* URL для приёма ВХОДЯЩИХ SMS Telnyx (OTP при регистрации номера в WhatsApp Cloud API) */
function telnyxSmsWebhook(db) { const base = process.env.PUBLIC_BASE_URL || tunnelUrl() || global.LUMEN_BASE || ''; return (base && !/localhost|127\.0\.0\.1/.test(base)) ? base.replace(/\/$/, '') + '/hooks/telnyx-sms?key=' + encodeURIComponent(db.settings.hooks.secret) : ''; }
/* Гарантируем messaging-profile у Telnyx с нашим inbound-вебхуком — иначе входящие SMS (OTP) некуда доставлять.
   Профиль привязывается к номеру → SMS с этого номера летят к нам → OTP появляется в CRM. */
async function ensureTelnyxMsgProfile(db) {
  const t = db.settings.telephony || (db.settings.telephony = {});
  const hook = telnyxSmsWebhook(db);
  if (t.msgProfileId) { try { if (hook) await telnyxApi(db, 'PATCH', '/messaging_profiles/' + t.msgProfileId, { webhook_url: hook }); } catch (_) {} return t.msgProfileId; }
  const nm = 'Lumen OTP ' + ((db.settings.agency && db.settings.agency.name) || '');
  const j = await telnyxApi(db, 'POST', '/messaging_profiles', { name: nm.slice(0, 60), webhook_url: hook || undefined, whitelisted_destinations: ['US', 'GB', 'NL', 'CA', 'DE', 'FR', 'IL', 'UA', 'AE', 'PL', 'ES', 'IT'] });
  t.msgProfileId = j.data && j.data.id; store.save();
  return t.msgProfileId;
}

/* --- Yesim Virtual Numbers: покупка виртуальных номеров под СЕРЫЕ WhatsApp (номер ловит OTP по SMS) --- */
/* Платформенный токен (SaaS): все агентства покупают серые номера через ОДИН наш Yesim-аккаунт. Basic-Auth
   (username=token, password=token). ⚠️ Yesim требует whitelist IP сервера в их дашборде. */
function yesimCreds() { try { const r = store.getRegistry(); const p = r.platformYesim || {}; return { user: process.env.YESIM_USER || p.user || '', token: process.env.YESIM_TOKEN || p.token || '' }; } catch (_) { return { user: process.env.YESIM_USER || '', token: process.env.YESIM_TOKEN || '' }; } }
function yesimToken() { return yesimCreds().token; }
async function yesimApi(action, params) {
  const { user, token } = yesimCreds(); if (!token) throw new Error('Yesim-токен не задан (оператор: задай в реестре platformYesim)');
  /* Basic-auth: username=API user, password=token (в дашборде это две колонки) */
  const auth = 'Basic ' + Buffer.from((user || token) + ':' + token).toString('base64');
  const body = new URLSearchParams();
  if (params) for (const k of Object.keys(params)) if (params[k] != null) body.set('params[' + k + ']', String(params[k]));
  const r = await fetch('https://vn.yesim.app/apiv1/index.php?action=' + action, { method: 'POST', headers: { Authorization: auth, 'Content-Type': 'application/x-www-form-urlencoded' }, body: body.toString(), signal: AbortSignal.timeout(15000) });
  const txt = await r.text(); let j = {}; try { j = JSON.parse(txt); } catch (_) { j = { raw: txt.slice(0, 300) }; }
  if (!r.ok) throw new Error('yesim ' + r.status + ': ' + (j.error || j.message || j.raw || 'ошибка'));
  return j;
}
async function serverPublicIp() { try { const r = await fetch('https://api.ipify.org?format=json', { signal: AbortSignal.timeout(6000) }); const j = await r.json(); return j.ip || ''; } catch (_) { return ''; } }

/* --- Серый WhatsApp: обращение к облачному воркеру (Baileys) --- */
/* sessionId воркера тенант-скоупный: <tid>__<phone> — номера разных агентств не пересекаются */
const waGraySid = (phone) => store.currentTid() + '__' + String(phone || '').replace(/[^0-9]/g, '');
/* URL/токен серого воркера: env → платформенный реестр (оператор задал ОДИН раз в CRM) → настройки тенанта →
   дефолтный URL. Смысл SaaS: оператор настраивает воркер один раз, новые агентства НИЧЕГО не вводят. */
const DEFAULT_WA_WORKER = 'https://lumen-wa-worker-production.up.railway.app';
function _platWorker() { try { const r = store.getRegistry(); return r.platformWorker || {}; } catch (_) { return {}; } }
/* env-URL воркера часто задают без схемы (railway.app/...) → fetch() «Failed to parse URL». Нормализуем. */
function normWorkerUrl(u) { u = String(u || '').trim().replace(/\/$/, ''); if (u && !/^https?:\/\//i.test(u)) u = 'https://' + u; return u; }
function waWorkerBase(db) { return normWorkerUrl(process.env.LUMEN_WA_WORKER_URL || _platWorker().url || (db.settings.waGray && db.settings.waGray.url) || DEFAULT_WA_WORKER); }
function waWorkerToken(db) { return process.env.LUMEN_WA_WORKER_TOKEN || _platWorker().token || (db.settings.waGray && db.settings.waGray.token) || ''; }
function waWorkerReady(db) { return !!(waWorkerBase(db) && waWorkerToken(db)); }
/* платформенный режим (агентству не вводить URL/токен) = задан платформенный токен (env или реестр) */
function waWorkerPlatform() { return !!(process.env.LUMEN_WA_WORKER_TOKEN || _platWorker().token); }
async function waGrayApi(db, method, pathx, body) {
  const base = waWorkerBase(db);
  if (!base) throw new Error('WA-воркер не настроен (укажи URL в Настройках)');
  const r = await fetch(base + pathx, {
    method,
    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + waWorkerToken(db) },
    body: body ? JSON.stringify(body) : undefined,
  });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error('worker ' + r.status + ': ' + (j.error || 'ошибка'));
  return j;
}

/* ── Серый TELEGRAM (MTProto user-accounts) — воркер lumen-tg-worker, аналог WA-воркера ── */
function tgWorkerBase(db) { const r = store.getRegistry(); return normWorkerUrl(process.env.LUMEN_TG_WORKER_URL || (r.platformTgWorker && r.platformTgWorker.url) || (db.settings.tgGray && db.settings.tgGray.url) || ''); }
function tgWorkerToken(db) { const r = store.getRegistry(); return process.env.LUMEN_TG_WORKER_TOKEN || (r.platformTgWorker && r.platformTgWorker.token) || (db.settings.tgGray && db.settings.tgGray.token) || ''; }
function tgWorkerReady(db) { return !!(tgWorkerBase(db) && tgWorkerToken(db)); }
function tgGraySid(phone) { return 'tg_' + String(phone).replace(/[^0-9]/g, ''); }
async function tgGrayApi(db, method, pathx, body) {
  const base = tgWorkerBase(db); if (!base) throw new Error('TG-воркер не настроен (LUMEN_TG_WORKER_URL / platformTgWorker)');
  const r = await fetch(base + pathx, { method, headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + tgWorkerToken(db) }, body: body ? JSON.stringify(body) : undefined });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error('tg-worker ' + r.status + ': ' + (j.error || 'ошибка'));
  return j;
}

/* Автоподбор серого номера для лида: залипание за лидом → номер закреплённого брокера → любой подключённый.
   `live` — карта сессий из воркера (GET /sessions). Возвращает запись номера или null (нет подключённых). */
/* Потолок «первых касаний НОВЫМ лидам» на серый номер в сутки (защита от бана).
   Действующие диалоги (у лида уже есть grayPhone) НЕ считаются и НЕ ограничиваются. */
function grayNewLeadCap(db) { const g = db.settings.waGray || {}; return g.newLeadCapPerDay || 5; }
function grayNewToday(n) { const today = new Date().toISOString().slice(0, 10); return n._newLeadDay === today ? (n._newLeadsToday || 0) : 0; }
function pickGrayNumber(db, lead, live) {
  const g = db.settings.waGray || {};
  const connected = (g.numbers || []).filter(n => { const s = live[waGraySid(n.phone)]; return s && s.status === 'connected' && (!n.roles || n.roles.send !== false); });
  if (!connected.length) return null;
  if (lead.grayPhone) { const s = connected.find(n => n.phone === lead.grayPhone); if (s) return s; }          /* действующий диалог: вся цепочка с одного номера, без лимита */
  /* НОВЫЙ лид (первое касание): потолок новых лидов — МЯГКИЙ. Предпочитаем номер под лимитом,
     но НЕ блокируем отправку (только френдли-предупреждение в graySender). Закреп за брокером в приоритете. */
  const cap = grayNewLeadCap(db);
  if (lead.broker) { const b = connected.find(n => n.brokerId === lead.broker); if (b) return b; }             /* прогретый номер закреплённого брокера */
  const under = connected.filter(n => grayNewToday(n) < cap);
  const pool = under.length ? under : connected;                                                                /* под лимитом, иначе — все (мягко) */
  return pool.sort((a, b) => grayNewToday(a) - grayNewToday(b))[0];                                             /* наименее нагруженный новыми лидами */
}

/* Серый транспорт для engine.send: реальная отправка с прогретого номера брокера через Baileys-воркер.
   Нет подключённого номера ИЛИ серый не настроен → тихий мок (поведение как раньше, ничего не ломаем). */
engine.setGraySender(async (db, lead, m) => {
  const g = db.settings.waGray || {};
  if (!waWorkerReady(db) || !(g.numbers || []).length || !lead.phone) { m.status = 'delivered'; store.save(); return; }   /* FIX: платформенный воркер (env) → g.url/token пусты; раньше тут всё уходило в мок */
  let live = {}; try { live = (await waGrayApi(db, 'GET', '/sessions')).sessions || {}; } catch (_) { m.status = 'delivered'; store.save(); return; }
  const wasNew = !lead.grayPhone;
  const num = pickGrayNumber(db, lead, live);
  if (!num) { m.status = 'delivered'; store.save(); return; }   /* нет подключённых — прежний мок, не ломаем поток */
  await waGrayApi(db, 'POST', '/sessions/' + waGraySid(num.phone) + '/send', { to: lead.phone, text: m.text });
  lead.grayPhone = num.phone;                    /* закрепляем номер за лидом — цепочка остаётся на нём */
  if (wasNew) {
    const today = new Date().toISOString().slice(0, 10);
    if (num._newLeadDay !== today) { num._newLeadDay = today; num._newLeadsToday = 0; }
    num._newLeadsToday = (num._newLeadsToday || 0) + 1;   /* учёт первого касания новому лиду */
    /* МЯГКИЙ потолок: шлём в любом случае, но если превысили — френдли-предупреждение (не блок) */
    const cap = grayNewLeadCap(db);
    if (num._newLeadsToday > cap && !num._capWarnedDay) { num._capWarnedDay = today; ai.pushEvent(db, { type: 'note', text: `⚠️ Осторожно: с номера +${num.realPhone || num.phone} сегодня уже ${num._newLeadsToday} первых касаний новым лидам (реком. ≤${cap}). Много первых касаний с одного серого номера повышает риск бана — распределите новых лидов на другие номера или добавьте номер.` }); }
    else if (num._capWarnedDay !== today) { num._capWarnedDay = null; }
  }
  m.numberId = num.phone; m.grayFrom = num.phone; m.status = 'delivered';
  store.save();
});

/* --- Серый прогрев: подключённые номера тенанта периодически переписываются между собой --- */
const WARMUP_MSGS = ['Привет! Как дела?', 'Ты на созвоне сегодня?', 'Скинь потом отчёт', 'Ок, договорились 👍', 'Спасибо!', 'Доброе утро ☀️', 'Обедаем в час?', 'Готово, посмотри', 'Хорошего дня', 'Наберу чуть позже', 'Всё в силе?', 'Принял, спасибо'];
let warmupBusy = false;
async function warmupTick() {
  if (warmupBusy) return; warmupBusy = true;
  try {
    for (const tid of store.listTenants()) {
      await store.runInTenant(tid, async () => {
        const db = store.get();
        const g = db.settings.waGray;
        if (!g || !g.warmup || !g.warmup.running) return;
        if (!waWorkerReady(db)) return;   /* FIX: воркер платформенный (env) → g.url пустой; раньше здесь выходили и прогрев НИКОГДА не шёл */
        const today = new Date().toISOString().slice(0, 10);
        if (g.warmup._day !== today) { g.warmup._day = today; g.warmup._sent = 0; }
        const cap = (g.warmup.perDay || 16) * Math.max(1, (g.numbers || []).length);
        if ((g.warmup._sent || 0) >= cap) return;
        let live = {};
        try { const r = await waGrayApi(db, 'GET', '/sessions'); live = r.sessions || {}; } catch (e) { return; }
        /* сессия адресуется ключом пула (n.phone), а РЕАЛЬНЫЙ номер-получатель берём из live.phone (воркер узнаёт его после коннекта) */
        /* FIX: переподключённый по QR номер может не отдать live.phone сразу → фолбэк на сохранённый n.realPhone,
           иначе вернувшийся номер молча выпадал из ротации прогрева (был реальный баг). */
        const conn = (g.numbers || []).map(n => ({ n, real: (live[waGraySid(n.phone)] || {}).phone || n.realPhone || '', status: (live[waGraySid(n.phone)] || {}).status })).filter(x => x.status === 'connected' && /^\d{7,15}$/.test(String(x.real || '')));
        if (conn.length < 2) return;
        const i = Math.floor(Math.random() * conn.length);
        let k = Math.floor(Math.random() * conn.length); if (k === i) k = (k + 1) % conn.length;
        const from = conn[i], to = conn[k];
        const msg = WARMUP_MSGS[Math.floor(Math.random() * WARMUP_MSGS.length)];
        try {
          await waGrayApi(db, 'POST', '/sessions/' + waGraySid(from.n.phone) + '/send', { to: to.real, text: msg });
          g.warmup._sent = (g.warmup._sent || 0) + 1;
          g.warmup.total = (g.warmup.total || 0) + 1;
          g.warmup.lastAt = Date.now();
          g.warmup.log = [{ from: from.n.label || from.real, to: to.n.label || to.real, text: msg, at: Date.now() }].concat(g.warmup.log || []).slice(0, 40);
          store.save();
        } catch (e) {}
      });
    }
  } finally { warmupBusy = false; }
}
setInterval(() => { warmupTick().catch(() => {}); }, 12 * 60e3);   /* каждые ~12 мин, cost-safe */

/* ── Умный вотчер отвала серых WA-номеров: connected→не connected = алерт (в центр + Telegram владельцу),
   не connected→connected = «вернулся». Чтобы отвалившийся номер не пропал молча (прогрев/касания встают). ── */
let waDropWatchBusy = false;
async function waDropWatch() {
  if (waDropWatchBusy) return; waDropWatchBusy = true;
  try {
    for (const tid of store.listTenants()) {
      await store.runInTenant(tid, async () => {
        const db = store.get(); const g = db.settings.waGray;
        if (!g || !(g.numbers || []).length || !waWorkerReady(db)) return;
        let live = {}; try { const r = await waGrayApi(db, 'GET', '/sessions'); live = r.sessions || {}; } catch (e) { return; }
        let changed = false;
        for (const n of g.numbers) {
          const s = live[waGraySid(n.phone)] || {};
          const cur = s.status || 'none';
          const prev = (n.live && n.live.status) || 'none';
          const who = n.label || (n.realPhone ? '+' + n.realPhone : n.phone);
          if (prev === 'connected' && cur !== 'connected') {
            notify(db, { type: 'wa', level: 'critical', title: 'WhatsApp-номер отвалился', text: `Номер «${who}» больше не на связи. Срочно переподключите по QR в разделе «Номера» → WhatsApp QR — иначе прогрев и касания по нему встают.` });
          } else if (prev !== 'connected' && prev !== 'none' && cur === 'connected') {
            notify(db, { type: 'wa', level: 'success', title: 'WhatsApp-номер снова на связи', text: `Номер «${who}» переподключён — вернул в прогрев и касания.` });
          }
          n.live = Object.assign({}, n.live || {}, { status: cur, phone: s.phone || (n.live && n.live.phone) || null });
          changed = true;
        }
        if (changed) store.save();
      });
    }
  } finally { waDropWatchBusy = false; }
}
setInterval(() => { waDropWatch().catch(() => {}); }, 10 * 60e3);   /* каждые ~10 мин */

/* ── Прогрев серого TELEGRAM (по best-practice схеме, чтобы аккаунты не отлетали) ──
   • Возрастной рамп лимита отправки на аккаунт: день0 ≈3 → +2/день → потолок (perDay|20).
     Резкий скачок объёма = маркер спам-бота, поэтому наращиваем плавно ~5→20 за 2 недели.
   • Новый аккаунт (age 0, низкий cap) в основном ПРИНИМАЕт, а не шлёт («receive first»).
   • Рандомные from/to + джиттер интервала + вариативные тексты (не одинаковые) — имитация живого.
   • Только МЕЖДУ своими номерами пула (≥2 на связи). ⛔ Не рассылки. */
let tgWarmupBusy = false;
async function tgWarmupTick() {
  if (tgWarmupBusy) return; tgWarmupBusy = true;
  try {
    if (Math.random() < 0.25) return;   /* джиттер: иногда пропускаем тик → интервалы вразнобой */
    for (const tid of store.listTenants()) {
      await store.runInTenant(tid, async () => {
        const db = store.get();
        const g = db.settings.tgGray;
        if (!g || !g.warmup || !g.warmup.running) return;
        if (!tgWorkerReady(db)) return;
        const today = new Date().toISOString().slice(0, 10);
        if (g.warmup._day !== today) { g.warmup._day = today; g.warmup._sent = 0; (g.numbers || []).forEach(n => { n._warmSentToday = 0; }); }
        let live = {};
        try { const r = await tgGrayApi(db, 'GET', '/sessions'); live = r.sessions || {}; } catch (e) { return; }
        const conn = (g.numbers || []).map(n => ({ n, real: (live[tgGraySid(n.phone)] || {}).phone, status: (live[tgGraySid(n.phone)] || {}).status })).filter(x => x.status === 'connected' && /^\d{7,15}$/.test(String(x.real || '')));
        if (conn.length < 2) return;
        const capFor = (n) => { const start = n._warmStart || n.connectedAt || n.addedAt || Date.now(); const age = Math.floor((Date.now() - start) / 86400e3); return Math.min(g.warmup.perDay || 20, 3 + age * 2); };
        const eligible = conn.filter(x => (x.n._warmSentToday || 0) < capFor(x.n));
        if (!eligible.length) return;
        const from = eligible[Math.floor(Math.random() * eligible.length)];
        const others = conn.filter(x => x.n.phone !== from.n.phone);
        const to = others[Math.floor(Math.random() * others.length)];
        const msg = WARMUP_MSGS[Math.floor(Math.random() * WARMUP_MSGS.length)];
        try {
          await tgGrayApi(db, 'POST', '/sessions/' + tgGraySid(from.n.phone) + '/warmup', { toPhone: to.real, message: msg });
          if (!from.n._warmStart) from.n._warmStart = from.n.connectedAt || from.n.addedAt || Date.now();
          from.n._warmSentToday = (from.n._warmSentToday || 0) + 1;
          g.warmup._sent = (g.warmup._sent || 0) + 1; g.warmup.total = (g.warmup.total || 0) + 1; g.warmup.lastAt = Date.now();
          g.warmup.log = [{ from: (from.n.persona && from.n.persona.name) || from.real, to: (to.n.persona && to.n.persona.name) || to.real, text: msg, at: Date.now() }].concat(g.warmup.log || []).slice(0, 40);
          store.save();
        } catch (e) {}
      });
    }
  } finally { tgWarmupBusy = false; }
}
setInterval(() => { tgWarmupTick().catch(() => {}); }, 14 * 60e3);   /* ~14 мин, вразнобой с WA-тиком */

/* ── Авто-синк рекламного кабинета Meta (Marketing API): расход/кампании + лиды из лид-форм ──
   Marketing API у Meta бесплатный (нет платы за вызовы) — cost-safe тут про rate-limit и compute:
   тик раз в ~30 мин, но для тенанта реально дёргаем не чаще интервала (по умолчанию 6 ч). */
let metaAdsBusy = false;
async function metaAdsTick() {
  if (metaAdsBusy) return; metaAdsBusy = true;
  try {
    for (const tid of store.listTenants()) {
      await store.runInTenant(tid, async () => {
        const db = store.get();
        if (!metaads.apiEnabled(db)) return;
        const c = db.settings.metaAds;
        const everyMs = Math.max(1, (c.syncEveryHours || 6)) * 3600e3;
        if (c.lastSyncAt && (Date.now() - c.lastSyncAt) < everyMs) return;
        try { await metaads.sync(db, { matchAd, nextId: store.nextId, pushEvent: ai.pushEvent, save: () => store.save() }); } catch (e) {}
      });
    }
  } finally { metaAdsBusy = false; }
}
/* сквозной прогрев фермы: номер пула шлёт сообщения пирам через платформенный WA-воркер
   (номер должен быть залинкован как сессия waGraySid(phone); иначе /send отдаст ошибку — тихо пропустим) */
farmWarm.setWarmSender(async (fromPhone, toPhone, text) => {
  return store.runInTenant(store.PRIMARY, () => {
    const db = store.get();
    return waGrayApi(db, 'POST', '/sessions/' + waGraySid(fromPhone) + '/send', { to: toPhone, text });
  });
});
/* авто-тик прогрева: раз в час продвигаем все warming-номера (дневная норма + выпуск в ready) */
setInterval(() => { try { store.runInTenant(store.PRIMARY, () => farmWarm.tick()); } catch (_) {} }, 60 * 60e3);

/* тик баланса фермы: пересчитать состояния аренды, записать гейт «держи баланс» в БД
   каждого агентства (владелец/маркетолог увидит принуд. форму), поднять алерты основателю. */
function runBillingTick() {
  try {
    const bt = farmSvc.billingTick();               /* farm() глобальна — контекст тенанта не нужен */
    const gates = (bt && bt.gates) || {};
    for (const tid of store.listTenants()) {
      if (tid === store.PRIMARY) continue;
      const g = gates[tid] || { active: false };
      store.runInTenant(tid, () => {
        const db = store.get();
        const next = g.active
          ? { active: true, level: g.level, daysLeft: g.daysLeft, amount: g.amount, dueAt: g.dueAt, graceEndsAt: g.graceEndsAt, numbers: g.numbers, claim: g.clientClaim || null }
          : { active: false };
        if (JSON.stringify(next) !== JSON.stringify(db.settings.billingGate || null)) { db.settings.billingGate = next; store.saveNow(); }
      });
    }
  } catch (_) {}
}
setInterval(runBillingTick, 6 * 60 * 60e3);   /* каждые 6 ч */
setTimeout(runBillingTick, 15e3);             /* и вскоре после старта — чтобы гейты подтянулись сразу */

/* Проверка связи с Viber BSP (Infobip): валиден ли ключ+baseUrl+доступ.
   Безопасно — GET баланса (сообщение НЕ шлём и не тратим). Если передан `to` — ещё и
   реальная тест-отправка на этот номер (проверяет верификацию отправителя). */
async function viberTestConn(vb, to, agencyName) {
  vb = vb || {};
  const base = String(vb.baseUrl || '').replace(/^https?:\/\//, '').replace(/\/$/, '');
  const key = vb.apiKey || '';
  if (!key) return { ok: false, error: 'не задан API-ключ BSP (Настройки → Viber)' };
  if (!base) return { ok: false, error: 'не задан Base URL (вида xxxxx.api.infobip.com)' };
  const out = { ok: false, base, sender: vb.sender || '', mode: vb.mode || 'pa' };
  try {
    const r = await fetch('https://' + base + '/account/1/balance', { headers: { Authorization: 'App ' + key, Accept: 'application/json' } });
    const j = await r.json().catch(() => ({}));
    if (r.status === 401 || r.status === 403) return Object.assign(out, { error: 'ключ отклонён Infobip (401/403) — проверьте API-ключ' });
    if (!r.ok) return Object.assign(out, { error: 'Infobip ' + r.status + ': ' + (j.requestError && j.requestError.serviceException && j.requestError.serviceException.text || 'ошибка') });
    out.ok = true; out.balance = j.balance; out.currency = j.currency;
  } catch (e) { return Object.assign(out, { error: 'сеть/Base URL недоступен: ' + e.message }); }
  if (!vb.sender) out.warn = 'ключ валиден, но не задано имя-отправитель (Viber sender) — исходящие BSP не пойдут';
  /* опциональная реальная отправка (проверка верификации отправителя) */
  if (out.ok && to) {
    const phone = String(to).replace(/\D/g, '');
    try {
      const rs = await fetch('https://' + base + '/viber/2/messages', {
        method: 'POST', headers: { Authorization: 'App ' + key, 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({ messages: [{ sender: vb.sender, destinations: [{ to: phone }], content: { text: 'Lumen · тест связи Viber (' + (agencyName || 'агентство') + '). Если видите это — канал работает.', type: 'TEXT' } }] }),
      });
      const js = await rs.json().catch(() => ({}));
      if (!rs.ok) out.sendError = 'отправка ' + rs.status + ': ' + (js.requestError && js.requestError.serviceException && js.requestError.serviceException.text || rs.status);
      else out.sent = { to: phone, messageId: (js.messages && js.messages[0] && js.messages[0].messageId) || null, status: (js.messages && js.messages[0] && js.messages[0].status && js.messages[0].status.name) || 'ACCEPTED' };
    } catch (e) { out.sendError = 'сеть: ' + e.message; }
  }
  return out;
}

/* ============ ПЕРЕДАЧА ФЕРМОВОГО НОМЕРА АГЕНТСТВУ (handover при покупке места) ============
   Пометки agencyTid в реестре фермы мало: чтобы брокеры РЕАЛЬНО пользовались номером, нужно
   (1) завести номер в каналы тенанта (waGray+tgGray) с привязкой брокера — тогда он виден в CRM
   и участвует в выборе отправителя; (2) перенести ПРОГРЕТУЮ сессию воркера из неймспейса
   прогрева (primary__<цифры>) в неймспейс агентства (<tid>__<цифры>) — тогда входящие
   маршрутизируются агентству (роутинг по префиксу sid). Session-reassign — best-effort:
   если сессии/воркера ещё нет, номер подключат по QR под неймспейсом агентства позже. */
async function farmHandoverToTenant(num, agencyTid, brokerId, displayName) {
  const digits = String((num && num.phone) || '').replace(/\D/g, '');
  if (!digits || !agencyTid || agencyTid === store.PRIMARY) return;
  const label = displayName || (num && num.displayName) || ('Ферма ' + digits.slice(-4));
  store.runInTenant(agencyTid, () => {
    const db = store.get();
    db.settings.waGray = db.settings.waGray || { numbers: [], warmup: { running: false, perDay: 16 } };
    db.settings.waGray.numbers = db.settings.waGray.numbers || [];
    let w = db.settings.waGray.numbers.find(n => String(n.phone).replace(/\D/g, '') === digits);
    if (!w) { w = { phone: digits, roles: { send: true, call: false }, source: 'farm', addedAt: Date.now() }; db.settings.waGray.numbers.push(w); }
    w.label = label; w.farmId = num.id; w.brokerId = brokerId || w.brokerId || null;
    db.settings.tgGray = db.settings.tgGray || { numbers: [] };
    db.settings.tgGray.numbers = db.settings.tgGray.numbers || [];
    let t = db.settings.tgGray.numbers.find(n => String(n.phone).replace(/\D/g, '') === digits);
    if (!t) { t = { phone: digits, persona: { name: label, avatar: '', about: '', mode: 'qualifier', brokerId: brokerId || null }, source: 'farm', farmId: num.id, addedAt: Date.now() }; db.settings.tgGray.numbers.push(t); }
    else { t.persona = t.persona || {}; t.persona.brokerId = brokerId || t.persona.brokerId || null; t.label = label; }
    store.saveNow();
  });
  try { await store.runInTenant(store.PRIMARY, () => waGrayApi(store.get(), 'POST', '/sessions/' + store.PRIMARY + '__' + digits + '/reassign', { to: agencyTid + '__' + digits })); } catch (e) {}
}
/* возврат номера в пул: убрать из каналов бывшего тенанта + вернуть сессию в неймспейс прогрева */
async function farmReclaimFromTenant(prevTid, phone) {
  const digits = String(phone || '').replace(/\D/g, '');
  if (!digits || !prevTid || prevTid === store.PRIMARY) return;
  store.runInTenant(prevTid, () => {
    const db = store.get();
    if (db.settings.waGray && db.settings.waGray.numbers) db.settings.waGray.numbers = db.settings.waGray.numbers.filter(n => String(n.phone).replace(/\D/g, '') !== digits);
    if (db.settings.tgGray && db.settings.tgGray.numbers) db.settings.tgGray.numbers = db.settings.tgGray.numbers.filter(n => String(n.phone).replace(/\D/g, '') !== digits);
    store.saveNow();
  });
  try { await store.runInTenant(store.PRIMARY, () => waGrayApi(store.get(), 'POST', '/sessions/' + prevTid + '__' + digits + '/reassign', { to: store.PRIMARY + '__' + digits })); } catch (e) {}
}

/* ============ АВТО-ТРАНСКРИПЦИЯ ВСТРЕЧ (Zoom/Meet/Teams) — meeting-бот (Recall.ai) ============
   SaaS-модель: ОДИН платформенный ключ (env RECALL_API_KEY) → работает для ВСЕХ агентств
   автоматически, настраивать ничего не надо. Бронь встречи с Zoom/Meet-ссылкой → бот сам
   заходит → транскрипт+ИИ-резюме в карточку. Стоимость — расходник платформы. */
async function maybeScheduleMeetingBot(db, mt) {
  try {
    if ((db.settings.meetingBot || {}).enabled === false) return;
    if (!meetingBot.ready()) return;                                          /* нет платформенного ключа → тихо */
    if (!mt || !mt.link || !meetingBot.isSupportedMeetingUrl(mt.link)) return; /* только Zoom/Meet/Teams (не Jitsi) */
    const r = await meetingBot.scheduleBot(mt.link, mt.at, { meetingId: mt.id, leadId: mt.leadId, tid: store.currentTid() });
    if (r.ok) { mt.botId = r.botId; mt.transcriptStatus = 'scheduled'; }
    else { mt.transcriptStatus = 'error'; mt.transcriptError = String(r.error || '').slice(0, 140); }
    store.save();
  } catch (_) {}
}
async function ingestMeetingTranscript(db, mt) {
  if (!mt || !mt.botId || mt.transcriptStatus === 'done') return false;
  const r = await meetingBot.fetchTranscript(mt.botId);
  if (!r.ok || !r.text) return false;
  const lead = (db.leads || []).find(l => l.id === mt.leadId); if (!lead) return false;
  lead.transcripts = lead.transcripts || [];
  const kindRu = { call: 'Созвон', video: 'Видео-встреча', tour: 'Показ' }[mt.kind] || 'Встреча';
  lead.transcripts.push({ id: store.nextId('tr'), at: Date.now(), label: kindRu + ' (авто-запись)', text: r.text.slice(0, 40000), audio: null, meetingId: mt.id });
  mt.transcript = r.text.slice(0, 40000); mt.transcriptStatus = 'done'; mt.transcriptAt = Date.now();
  ai.pushEvent(db, { type: 'meeting', leadId: lead.id, text: `Транскрипт встречи готов (${kindRu}) — в карточке лида` });
  store.save();
  if (llm.available()) { try { const sum = await llm.summarize(db, lead); if (sum) { lead.summary = sum; lead.summaryAt = Date.now(); store.save(); } } catch (_) {} }
  return true;
}
/* поллинг-фолбэк: добрать транскрипты завершившихся встреч, если вебхук не пришёл */
async function meetingBotTick() {
  if (!meetingBot.ready()) return;
  for (const tid of store.listTenants()) {
    try {
      await store.runInTenant(tid, async () => {
        const db = store.get(); const now = Date.now();
        const pend = (db.meetings || []).filter(mt => mt.botId && mt.transcriptStatus === 'scheduled' && (mt.at + (mt.dur || 60) * 60e3 + 3 * 60e3) < now);
        for (const mt of pend.slice(0, 5)) await ingestMeetingTranscript(db, mt).catch(() => {});
      });
    } catch (_) {}
  }
}
setInterval(() => { meetingBotTick().catch(() => {}); }, 10 * 60e3);

/* ============ HEADLESS-РЕНДЕР СТРАНИЦ (для импорта объектов «по ссылке» с SPA/JS-сайтов) ============
   У источников недвижимости нет API, а многие — SPA (Bubble/React) → обычный fetch отдаёт пустой
   каркас. Провайдер рендера (Firecrawl по умолчанию) исполняет JS и возвращает готовый markdown+html.
   Платформенный ключ env RENDER_API_KEY → работает для ВСЕХ агентств (SaaS, как Recall.ai). Нет
   ключа → возвращает null, пайплайн падает на обычный fetch (server-rendered сайты и так работают). */
/* размеры картинки из бинарного заголовка (без библиотек): JPEG/PNG/WebP → {w,h} или null.
   Нужно чтобы отсекать низкое разрешение при импорте (клиенту — только продающие фото). */
function imgDimensions(buf) {
  try {
    if (!buf || buf.length < 24) return null;
    /* PNG */
    if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4E && buf[3] === 0x47) return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20) };
    /* WebP (RIFF....WEBP) */
    if (buf[0] === 0x52 && buf[1] === 0x49 && buf[2] === 0x46 && buf[3] === 0x46 && buf[8] === 0x57 && buf[9] === 0x45 && buf[10] === 0x42 && buf[11] === 0x50) {
      const f = buf.toString('ascii', 12, 16);
      if (f === 'VP8 ') return { w: buf.readUInt16LE(26) & 0x3FFF, h: buf.readUInt16LE(28) & 0x3FFF };
      if (f === 'VP8L') { const b = buf.readUInt32LE(21); return { w: (b & 0x3FFF) + 1, h: ((b >> 14) & 0x3FFF) + 1 }; }
      if (f === 'VP8X') return { w: buf.readUIntLE(24, 3) + 1, h: buf.readUIntLE(27, 3) + 1 };
      return null;
    }
    /* JPEG: ищем SOF0..SOF3 маркеры */
    if (buf[0] === 0xFF && buf[1] === 0xD8) {
      let o = 2;
      while (o < buf.length - 9) {
        if (buf[o] !== 0xFF) { o++; continue; }
        const mk = buf[o + 1];
        if (mk >= 0xC0 && mk <= 0xC3) return { h: buf.readUInt16BE(o + 5), w: buf.readUInt16BE(o + 7) };
        o += 2 + buf.readUInt16BE(o + 2);
      }
    }
  } catch (_) {}
  return null;
}
function renderReady() { return !!process.env.RENDER_API_KEY; }
async function renderPage(url) {
  const key = process.env.RENDER_API_KEY || ''; if (!key) return null;
  const provider = process.env.RENDER_PROVIDER || 'firecrawl';
  try {
    if (provider === 'firecrawl') {
      const r = await fetch('https://api.firecrawl.dev/v1/scrape', {
        method: 'POST', headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
        body: JSON.stringify({ url, formats: ['markdown', 'html'], onlyMainContent: false, waitFor: 2500, timeout: 25000 }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok || !j.success || !j.data) return null;
      const d = j.data, md = d.metadata || {};
      return { markdown: d.markdown || '', html: d.html || '', title: md.title || md.ogTitle || '', ogImage: md.ogImage || md['og:image'] || '' };
    }
  } catch (_) {}
  return null;
}

/* веб-поиск по открытым источникам (Firecrawl /search — тот же ключ RENDER_API_KEY).
   Для обогащения карточек: чего нет на портале (срок сдачи, доходность, ход стройки) — ищем в вебе. */
async function webSearch(query, limit, opts) {
  const key = process.env.RENDER_API_KEY || ''; if (!key || !query) return null;
  const wantMedia = !!(opts && opts.media);   /* собрать фото/видео из выдачи (комплексное обогащение) */
  try {
    const r = await fetch('https://api.firecrawl.dev/v1/search', {
      method: 'POST', headers: { Authorization: 'Bearer ' + key, 'Content-Type': 'application/json' },
      body: JSON.stringify({ query, limit: limit || 5, scrapeOptions: { formats: wantMedia ? ['markdown', 'html'] : ['markdown'] } }),
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.success) return null;
    const items = (j.data || []).slice(0, limit || 5);
    const out = {
      text: items.map(x => `## ${x.title || ''} (${x.url || ''})\n${String(x.markdown || x.description || '').slice(0, 3200)}`).join('\n\n').slice(0, 16000),
      sources: items.map(x => ({ title: (x.title || '').slice(0, 120), url: x.url || '' })).filter(s => s.url),
    };
    if (wantMedia) {
      const imgs = new Set(), vids = new Set();
      for (const x of items) {
        const html = x.html || '', md = x.markdown || '', base = x.url || query;
        if (html) scrapeImagesFromHtml(html, base).forEach(u => { if (imgs.size < 60 && /\.(jpe?g|png|webp)(\?|$)/i.test(u) && !/favicon|logo|icon|sprite|avatar|placeholder|blank|banner|header|footer|\.svg(\?|$)/i.test(u)) imgs.add(u); });
        /* видео-рендеры: youtube / vimeo / прямые mp4 */
        const blob = html + '\n' + md;
        (blob.match(/https?:\/\/(?:www\.)?(?:youtube\.com\/watch\?v=|youtu\.be\/|player\.vimeo\.com\/video\/|vimeo\.com\/)[\w-]+/gi) || []).forEach(v => { if (vids.size < 12) vids.add(v); });
        (blob.match(/https?:\/\/[^\s"'<>]+\.mp4(\?[^\s"'<>]*)?/gi) || []).forEach(v => { if (vids.size < 12) vids.add(v); });
      }
      out.images = [...imgs]; out.videos = [...vids];
    }
    return out;
  } catch (_) { return null; }
}

/* Правдоподобная валюта цены: порталы часто отдают число без символа, ИИ ставит USD по умолчанию.
   Абсурдные суммы для гео чиним (напр. 5 090 000 в Камале = THB, а не $5M). */
function fixMoneyCurrency(geo, price, cur) {
  cur = String(cur || '').toUpperCase().replace(/[^A-Z]/g, ''); price = +price || 0;
  if (!/^(USD|EUR|AED|THB|RUB|IDR|GBP)$/.test(cur)) cur = '';
  if (!price) return cur || 'USD';
  if ((geo === 'phuket' || geo === 'thailand') && cur !== 'THB' && price > 1200000) return 'THB';
  if (geo === 'bali' && cur !== 'IDR' && price > 200000000) return 'IDR';
  return cur || (geo === 'phuket' || geo === 'thailand' ? 'THB' : 'USD');
}
/* онлайн-курсы валют (free, без ключа: open.er-api.com база USD), кэш на сутки */
let _fx = { at: 0, rates: null };
async function getFxRates() {
  if (_fx.rates && Date.now() - _fx.at < 24 * 3600e3) return _fx.rates;
  try {
    const r = await fetch('https://open.er-api.com/v6/latest/USD');
    const j = await r.json().catch(() => ({}));
    if (j && j.result === 'success' && j.rates && j.rates.THB) { _fx = { at: Date.now(), rates: j.rates }; return j.rates; }
  } catch (_) {}
  /* фолбэк-курсы (приблизительные), если API недоступен — лучше, чем ничего */
  return _fx.rates || { USD: 1, EUR: 0.92, AED: 3.67, THB: 36, RUB: 92, IDR: 15800, GBP: 0.79 };
}
const _geoCenters = {};   /* кэш центров регионов (Пхукет/Дубай…) для фолбэка геокодинга */
async function nominatim(q) {
  try {
    const r = await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' + encodeURIComponent(q), { headers: { 'User-Agent': 'LumenCRM/1.0 (real-estate)', 'Accept-Language': 'en' } });
    const j = await r.json().catch(() => ([]));
    return (Array.isArray(j) && j[0]) ? { lat: +j[0].lat, lng: +j[0].lon } : null;
  } catch (_) { return null; }
}

