          const to = String((pl.to && pl.to[0] && pl.to[0].phone_number) || pl.to || '').replace(/[^0-9]/g, '');
          const from = (pl.from && pl.from.phone_number) || pl.from || '';
          const text = pl.text || '';
          const code = ((text.match(/(\d[\d\- ]{2,7}\d)/) || [])[0] || '').replace(/[^0-9]/g, '');
