      const ct = req.headers['content-type'] || '';
      const ext = ct.includes('png') ? 'png' : ct.includes('webp') ? 'webp' : 'jpg';
      const dir = path.join(PUBLIC, 'assets', 'brokers');
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
