      if (!refB64) { try { refB64 = fs.readFileSync(path.join(PUBLIC, 'assets', 'ref', 'layan-benchmark.png')).toString('base64'); } catch (e) { refB64 = ''; } }
      const rh = c.format === 'story' ? 1920 : c.format === 'square' ? 1080 : 1350;
      const results = [];
